-- Seed the ultrasound imaging-report template row (fix/ultrasound-template-fk).
--
-- WHY: Layer 4 (04-generate-soap.ts) writes `noteTemplateId: template.id`
-- UNCONDITIONALLY for every visit. SOAP specialties satisfy
-- transcribe_visits_noteTemplateId_fkey because their id is always a real
-- note_templates row (a doctor's custom template, or the seeded
-- 'tmpl_system_default_soap'). The ultrasound report template (id
-- 'tmpl_ultrasound_report') shipped in #341 ONLY in code, so persisting
-- any ultrasound visit hit a FK violation and the visit failed at the L4 write.
-- This seeds the matching row so ultrasound visits persist, mirroring how the
-- SOAP system default backs the same FK.
--
-- NOTES:
--   * isSystemDefault = false — the partial unique index
--     note_templates_one_system_default permits only ONE true row (held by
--     'tmpl_system_default_soap'). doctorId = NULL, so the doctor-scoped
--     listing (listDoctorTemplates: WHERE doctorId = <user>) never surfaces it
--     — invisible/non-selectable to SOAP users.
--   * Unlike the system-default row, this row is NOT read at generation time
--     (the in-code ULTRASOUND_REPORT_TEMPLATE constant is authoritative for L4),
--     so it carries no resync/drift-test obligation; sections/styleProfile
--     mirror the constant at seed time (isSystemDefault is forced false here
--     per the unique index above, diverging from the constant's `true`).
--   * DATA-only; idempotent (ON CONFLICT DO UPDATE); touches one row.

INSERT INTO "note_templates"
  ("id", "doctorId", "name", "encounterType", "sections", "styleProfile", "version", "status", "isSystemDefault", "createdAt", "updatedAt")
VALUES
  ('tmpl_ultrasound_report', NULL, 'Ultrasound Imaging Report', NULL,
   '[{"key":"exam","label":"Exam","order":1,"formatHint":"prose","styleInstructions":"One line: the study performed + laterality + sub-type, as stated. Examples:\n\"Venous Duplex Ultrasound — Bilateral Lower Extremities — Reflux/Insufficiency\"\n\"Venous Duplex Ultrasound — Right Lower Extremity — DVT Evaluation\"\n\"Duplex Ultrasound — Left GSV — Post-Ablation Follow-up\".\nIf the study type is ambiguous, state the most specific phrasing the\ndictation supports; do not invent a sub-type.","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"indication","label":"Indication","order":2,"formatHint":"prose","styleInstructions":"Why the study was ordered (symptoms, prior diagnosis, surveillance), as\nstated. e.g. \"Leg heaviness, aching, and visible varicosities\" /\n\"Left calf swelling, rule out DVT\" / \"Surveillance after RFA of the GSV\".\nIf not stated, write \"[not documented]\".","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"technique","label":"Technique","order":3,"formatHint":"prose","styleInstructions":"How the study was performed, only as stated. Typical elements: B-mode +\ncolor + spectral Doppler; patient position (e.g. reverse Trendelenburg /\nstanding for reflux, supine for DVT); reflux provocation (distal\naugmentation / Valsalva / cuff deflation); transverse compression at\nintervals for DVT. Do NOT assert a maneuver that was not dictated; if the\ntechnique is not described, write a single neutral line such as \"Standard\nduplex technique.\" rather than inventing specifics.","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"comparison","label":"Comparison","order":4,"formatHint":"prose","styleInstructions":"Prior study referenced for comparison (date/type), if mentioned, plus the\ninterval change if stated. If no prior is mentioned, write exactly:\n\"No prior study available for comparison.\"","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"findings","label":"Findings","order":5,"formatHint":"prose","styleInstructions":"Determine the STUDY TYPE from the dictation and structure the Findings with\nthe matching framework below. Report bilateral studies as a \"### Right\" block\nthen a \"### Left\" block. Attach measurements per segment. Include a segment\nline only if it was assessed; otherwise omit it or mark \"[not documented]\".\n\n— VENOUS REFLUX / INSUFFICIENCY —\nPer leg, per segment. Reflux time = duration of reverse flow after distal\naugmentation/Valsalva release, in seconds. Reflux convention (apply ONLY to\nlabel competent vs incompetent; never invent the time): pathologic reflux is\nreverse flow > 0.5 s in the superficial veins (GSV, SSV, accessory saphenous,\nperforators) and the deep CALF veins, and > 1.0 s in the femoropopliteal deep\nveins (CFV, FV, popliteal).\n  Deep system — Common Femoral Vein (CFV): patency, compressibility, phasic\n    flow, reflux time (s). Femoral Vein (FV): patency, reflux time (s).\n    Popliteal Vein: patency, reflux time (s).\n  Superficial system — Great Saphenous Vein (GSV): diameter (mm) at the\n    saphenofemoral junction (SFJ), proximal thigh, distal thigh, knee, and\n    calf as dictated; reflux time (s) per level; SFJ competence.\n    Small Saphenous Vein (SSV): diameter (mm), saphenopopliteal junction\n    (SPJ) competence, reflux time (s). Anterior accessory saphenous vein\n    (AASV) if assessed.\n  Perforators: location (e.g. mid-thigh/Hunterian, paratibial, posterior\n    tibial/Cockett), diameter (mm), and competence (incompetent if outward\n    flow > 0.5 s).\n\n— VENOUS DVT —\nPer leg, per segment: Common Femoral Vein, Femoral Vein (proximal/mid/distal\nas dictated), Popliteal Vein, and calf veins (posterior tibial, peroneal,\ngastrocnemius/soleal) if assessed. For each: compressibility (fully\ncompressible / non-compressible / partially compressible), flow (phasic,\naugments with distal compression / does not augment), and thrombus — present\nor absent; if present: acute (anechoic/hypoechoic, dilated, poorly\ncompressible, free-floating) vs chronic (echogenic, contracted, recanalized,\ncollaterals), and occlusive vs non-occlusive. State only what was dictated.\n\n— POST-ABLATION FOLLOW-UP —\nName the treated vein (e.g. GSV, SSV, AASV) and the modality if stated (RFA,\nEVLA/laser, mechanochemical, cyanoacrylate glue). Report: closure status —\noccluded/closed (non-compressible, echogenic, no flow) vs patent (flow\npresent = treatment failure); recanalization (none / partial / complete) and\nits segment extent; EHIT (endovenous heat-induced thrombosis) with Kabnick\nclass if the thrombus reaches the junction — Class 1: thrombus to the level\nof the SFJ/SPJ but not into the deep vein; Class 2: extension into the deep\nvein, < 50% lumen; Class 3: deep-vein extension ≥ 50% lumen; Class 4:\nocclusive deep-vein thrombosis — plus thrombus distance from the junction\n(mm/cm) if stated; and a residual-reflux check of untreated GSV/SSV/AASV/\nperforator segments.\n\n— ARTERIAL (lower-extremity, if dictated) —\nPer leg: ankle-brachial index (ABI) and segmental pressures if given;\nwaveform morphology (triphasic / biphasic / monophasic) at the common\nfemoral, superficial femoral, popliteal, and tibial levels; peak systolic\nvelocities (cm/s) and any stenosis grade; toe-brachial index (TBI) if stated.\n\n— VEIN MAPPING (pre-bypass / pre-access, if dictated) —\nTarget vein(s) (GSV, SSV, cephalic, basilic): diameter (mm) at multiple\nlevels, patency/continuity, depth from skin (mm), and suitability as stated.\n\n— OTHER STUDIES (abdominal, pelvic/OB, renal, thyroid & small parts,\n  echocardiogram, MSK, etc.) —\nUse the standard report structure for that study: report each organ/structure\nexamined with its standard measurements and laterality where applicable\n(e.g. renal length + cortical thickness + hydronephrosis per side; thyroid\nlobe dimensions + each nodule''s size and features; OB biometry GS/CRL/BPD/\nHC/AC/FL with EFW, fetal heart rate, presentation, placenta, amniotic fluid).\nReport ONLY structures and values the dictation provides; mark the rest\n\"[not documented]\". Do not fabricate a normal organ survey that was not\ndictated.","defaultText":null,"defaultTextMode":"omit_unless_supported"},{"key":"impression","label":"Impression","order":6,"formatHint":"numbered","styleInstructions":"Numbered conclusions that summarize the Findings — concise, one finding per\nline, with laterality. e.g. \"1. Incompetent right great saphenous vein with\n3.2 s reflux at the SFJ.\" / \"2. No deep venous thrombosis, bilateral.\" The\nImpression restates findings only; it adds no diagnosis, staging, or\nrecommendation the dictation did not contain.","defaultText":null,"defaultTextMode":"omit_unless_supported"}]'::jsonb,
   '{"tense":null,"tone":"concise professional radiology report","abbreviations":null,"preamble":"You are a vascular sonographer / radiologist transcribing a structured\ndiagnostic ULTRASOUND REPORT from a dictation. This is an IMAGING REPORT,\nNOT a SOAP clinical note — do NOT use Subjective/Objective/Assessment/Plan.\nUse ONLY the dictation (and any extracted entities) as evidence. Write in a\nconcise, professional radiology-report register.","globalRules":["- Do NOT invent clinical findings. If a claim lacks transcript\n  evidence, either omit it or explicitly mark it \"[not documented]\".","- When information came exclusively from the patient, prefix with\n  \"Per patient, …\" so the source is clear on downstream review.","- Never add test results, medication doses, or vital-sign numbers\n  that were not stated.","- Don''t add diagnostic qualifiers (acute, chronic, undiagnosed,\n  severe, mild, sudden, gradual) unless the transcript uses them\n  explicitly. \"Migraines\" stays \"migraines\" — not \"undiagnosed\n  migraines.\" Onset is \"sudden\" only if the patient said sudden.","- Don''t infer maternal/paternal side or a specific relative when\n  the transcript only mentions a relative type. \"My grandmother\"\n  stays \"grandmother\" — not \"maternal grandmother\" unless stated.","- When a dose, frequency, or strength is ambiguous in the\n  transcript, write what was actually said and append\n  ''[clarify with patient]'' rather than picking the most likely\n  value. Don''t silently resolve \"two tablets... one tablet twice\n  a day\" to a single interpretation.","- \"[unclear in recording]\" in the transcript means the audio was not\n  intelligible there. Never guess what it might have been. Never\n  assert a medication, dose, diagnosis, finding, or proper name whose\n  only evidence overlaps such a marker — reproduce the marker in the\n  note instead (e.g. ''prescribed [unclear in recording] — clarify'').","- Never present patient-reported sensations as examination findings.\n  \"Sore when I press on it\" is Subjective, per patient — it is NOT\n  \"tender to palpation\" unless the transcript documents a clinician\n  examination. If no exam occurred, the Objective section says so.","- Never normalize an unfamiliar, garbled, or partial term into a\n  specific drug or clinical term. If a word does not clearly match a\n  known medication or condition, quote it as heard with\n  ''[unclear in recording]'' appended rather than substituting the\n  closest real term.","- Never specify or elaborate a medication, device, or product beyond\n  what was said — even when the elaboration is pharmacologically\n  correct. A brand name stays as said: \"Implanon\" — do NOT append the\n  generic or route (\"etonogestrel subdermal implant\"). A vague device\n  reference stays vague: \"your injections\" is NOT \"adrenaline\n  auto-injector\" unless the transcript names it.","- Never assert possession, availability, or causal links that were\n  not stated. \"Takes salbutamol regularly\" does NOT become \"had her\n  inhaler on hand\". Two separately-mentioned facts (a hospitalisation;\n  an allergy) are NOT linked into one causal statement unless the\n  transcript links them.","- MEASUREMENTS ARE SACRED. Reproduce every numeric value EXACTLY as\n  dictated, with its unit: vein diameters in mm, reflux/reverse-flow\n  times in seconds (s), velocities in cm/s, distances in cm/mm. Never\n  round, convert, infer, or carry a value from one segment to another.\n  If a segment/structure was not assessed or no value was given, write\n  \"[not documented]\" — never a default or a typical value.","- LATERALITY IS SACRED. Right and Left are never interchangeable. Attribute\n  every finding to the side actually stated. If a finding''s side is\n  unclear in the dictation, write \"[laterality not specified]\" rather than\n  guessing. Report the Right side fully, then the Left side.","- Do NOT assign a final diagnosis the dictation does not support. The\n  Impression summarizes the findings (e.g. \"GSV reflux, right\") — it does\n  not add staging, etiology, or recommendations the reading physician did\n  not dictate.","- Output ONLY the ultrasound report markdown. No preamble, no postscript."]}'::jsonb,
   1, 'active', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO UPDATE SET
  "name" = EXCLUDED."name",
  "sections" = EXCLUDED."sections",
  "styleProfile" = EXCLUDED."styleProfile",
  "version" = EXCLUDED."version",
  "status" = EXCLUDED."status",
  "isSystemDefault" = EXCLUDED."isSystemDefault",
  "updatedAt" = CURRENT_TIMESTAMP;
